vector<int> parseList(string s) {
    vector<int> res;
    stringstream ss(s);
    string item;
    while (getline(ss, item, ',')) {
        size_t start = item.find_first_not_of(" \t\r\n");
        if (start != string::npos) {
            size_t end = item.find_last_not_of(" \t\r\n");
            res.push_back(stoi(item.substr(start, end - start + 1)));
        }
    }
    return res;
}

int main() {
