    while (getline(cin, line)) {
        if (line.empty()) continue;
        size_t bar = line.find('|');
        string s1 = (bar != string::npos) ? line.substr(0, bar) : line;
        string s2 = (bar != string::npos) ? line.substr(bar + 1) : "";
        vector<int> l1 = parseList(s1);
        vector<int> l2 = parseList(s2);
        vector<int> result = mergeSorted(l1, l2);
        for (size_t i = 0; i < result.size(); ++i) {
            cout << result[i];
            if (i < result.size() - 1) cout << ",";
        }
        cout << endl;
    }
    return 0;
